#include <iostream>

#include "minicpm5.hpp"

int main() {
  MiniCPM5Config config;
  config.model_path = "model/s100/minicpm5-2b_ctx4096_s100.hbm";
  config.tokenizer_path = "model/s100/tokenizer";
  config.template_path = "model/s100/tokenizer/simple-chat.jinja";
  config.prompt = "请用一句话介绍你自己。";
  config.text_sink = [](const char* chunk) {  // optional; omit for silent use
    std::cout << chunk << std::flush;
  };
  MiniCPM5 model(config);                    // stores settings only
  model.init();                              // loads model and tokenizer; one request per instance
  RequestOutcome outcome = model.predict();  // streams via the sink
  // consume: outcome.ended, outcome.failed, outcome.sdk_status, outcome.destroy_status,
  // outcome.stream_error; outcome.exit_code() is zero only for normal EOS with cleanup.
  return outcome.exit_code();
}

#include <iostream>

#include "minicpm5.hpp"

int main() {
  MiniCPM5Config config;
  config.model_path = "model/s100/minicpm5-2b_ctx4096_s100.hbm";
  config.tokenizer_path = "model/s100/tokenizer";
  config.template_path = "model/s100/tokenizer/simple-chat.jinja";
  config.prompt = "请用一句话介绍你自己。";
  config.text_sink = [](const char* chunk) {  // 可选；不设置则静默
    std::cout << chunk << std::flush;
  };
  MiniCPM5 model(config);                    // 仅保存配置
  model.init();                              // 加载模型与分词器；每个实例一次请求
  RequestOutcome outcome = model.predict();  // 经 sink 流式输出
  // 消费：outcome.ended、outcome.failed、outcome.sdk_status、outcome.destroy_status、
  // outcome.stream_error；仅正常 EOS 且成功释放时 outcome.exit_code() 为零。
  return outcome.exit_code();
}

#include "minicpm5.hpp"

int main() {
  minicpm5::Config config;              // model_path defaults to ../../model/s600
  config.max_new_tokens = 128;          // 1-4096
  minicpm5::MiniCPM5 model(config);     // validates settings, prepares the runtime; throws on failure
  minicpm5::Result first = model.Generate("What is 1+1?");  // opens the conversation
  if (first.status == 3) {              // 3 EOS; 6 output limit; 4 context limit
    // consume first.text, first.tokens, first.ttft_ms, first.decode_tps, first.e2e_ms
  }
  minicpm5::Result follow = model.Generate("Translate that.", false);  // same conversation
  return first.status == 3 && follow.status == 3 ? 0 : 1;
}

#include "minicpm5.hpp"

int main() {
  minicpm5::Config config;              // model_path 默认 ../../model/s600
  config.max_new_tokens = 128;          // 1-4096
  minicpm5::MiniCPM5 model(config);     // 校验配置并准备 runtime；失败抛异常
  minicpm5::Result first = model.Generate("What is 1+1?");  // 开启会话
  if (first.status == 3) {              // 3 EOS；6 生成上限；4 上下文上限
    // 消费 first.text、first.tokens、first.ttft_ms、first.decode_tps、first.e2e_ms
  }
  minicpm5::Result follow = model.Generate("Translate that.", false);  // 同一会话
  return first.status == 3 && follow.status == 3 ? 0 : 1;
}
